  LinearLayout macroCard(String label,String value,int accent){LinearLayout x=col();x.setPadding(dp(12),dp(12),dp(12),dp(12));x.setBackground(bg(SURFACE,18,LINE,1));x.addView(txt("●",10,accent,true),wrap());x.addView(txt(value,17,TEXT,true),match());x.addView(txt(label,8,SOFT,true),match());return x;}
