  TextView chip(String s){TextView t=txt(s,9,NIGHT,true);t.setGravity(Gravity.CENTER);t.setPadding(dp(10),dp(7),dp(10),dp(7));t.setBackground(bg(NEON,99,0,0));return t;}
  void spacer(LinearLayout r,int d){r.addView(new View(this),new LinearLayout.LayoutParams(dp(d),1));}

  String progressLabel(int used,int goal){if(used==0)return "Comece registrando sua primeira refeição";double z=used/(double)Math.max(1,goal);if(z<.55)return "Bom espaço para o restante do dia";if(z<.90)return "Você está avançando bem na meta";if(z<=1.05)return "Faixa próxima da sua meta diária";return "Meta ultrapassada — olhe a média semanal";}
  int streak(){Calendar c=Calendar.getInstance();int n=0;for(int i=0;i<7;i++){String k=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(c.getTime());if(calories(k)>0)n++;c.add(Calendar.DAY_OF_YEAR,-1);}return n;}
  int waterMl(){return p.getInt("water_"+key(),0);}void addWater(int ml){p.edit().putInt("water_"+key(),Math.min(10000,waterMl()+ml)).apply();}
  void repeatLast(){JSONArray a=today();if(a.length()==0){Toast.makeText(this,"Registre uma refeição primeiro.",Toast.LENGTH_SHORT).show();show("meals");return;}JSONObject last=a.optJSONObject(a.length()-1);if(last==null)return;try{JSONArray b=today();b.put(new JSONObject(last.toString()));p.edit().putString("entries_"+key(),b.toString()).apply();Toast.makeText(this,"Última refeição repetida.",Toast.LENGTH_SHORT).show();show("home");}catch(Exception ignored){}}
  Meal recommendation(int remaining){if(remaining<180)return null;int cap=Math.min(remaining,750);Meal best=null;for(Meal m:meals){if(m.k<=cap&&m.k>=220&&(best==null||m.k>best.k))best=m;}return best;}
  int[] macroEstimate(){int protein=0,carbs=0,fat=0;JSONArray a=today();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;int kcal=o.optInt("kcal");String n=o.optString("meal").toLowerCase(Locale.ROOT);double pp=.25,cp=.45,fp=.30;if(n.contains("frango")||n.contains("peixe")||n.contains("tilápia")||n.contains("atum")||n.contains("carne")||n.contains("bife")||n.contains("ovo")){pp=.32;cp=.38;fp=.30;}if(n.contains("macarr")||n.contains("lasanha")||n.contains("arroz")||n.contains("cuscuz")||n.contains("tapioca")){cp=.48;pp=.24;fp=.28;}protein+=(int)Math.round((kcal*pp)/4.0);carbs+=(int)Math.round((kcal*cp)/4.0);fat+=(int)Math.round((kcal*fp)/9.0);}return new int[]{protein,carbs,fat};}

  class CalorieRing extends View{Paint track=new Paint(Paint.ANTI_ALIAS_FLAG),arc=new Paint(Paint.ANTI_ALIAS_FLAG),big=new Paint(Paint.ANTI_ALIAS_FLAG),small=new Paint(Paint.ANTI_ALIAS_FLAG);int used,goal;CalorieRing(Context c,int u,int g){super(c);used=u;goal=Math.max(1,g);track.setStyle(Paint.Style.STROKE);track.setStrokeWidth(dp(11));track.setStrokeCap(Paint.Cap.ROUND);track.setColor(LINE);arc.setStyle(Paint.Style.STROKE);arc.setStrokeWidth(dp(11));arc.setStrokeCap(Paint.Cap.ROUND);arc.setColor(NEON);big.setColor(TEXT);big.setTextAlign(Paint.Align.CENTER);big.setTypeface(Typeface.create("sans",Typeface.BOLD));big.setTextSize(dp(25));small.setColor(SOFT);small.setTextAlign(Paint.Align.CENTER);small.setTypeface(Typeface.create("sans",Typeface.BOLD));small.setTextSize(dp(9));}@Override protected void onDraw(Canvas c){super.onDraw(c);float pad=dp(15),w=getWidth(),h=getHeight();RectF r=new RectF(pad,pad,w-pad,h-pad);c.drawArc(r,-90,360,false,track);c.drawArc(r,-90,(float)Math.min(360,360*(used/(double)goal)),false,arc);c.drawText(""+used,w/2,h/2+dp(4),big);c.drawText("KCAL",w/2,h/2+dp(22),small);}}
  class BrandMarkView extends View{Paint box=new Paint(Paint.ANTI_ALIAS_FLAG),stroke=new Paint(Paint.ANTI_ALIAS_FLAG),dot=new Paint(Paint.ANTI_ALIAS_FLAG);BrandMarkView(Context c){super(c);box.setColor(SURFACE2);stroke.setColor(NEON);stroke.setStyle(Paint.Style.STROKE);stroke.setStrokeCap(Paint.Cap.ROUND);stroke.setStrokeJoin(Paint.Join.ROUND);dot.setColor(NEON);}@Override protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),p=Math.max(3,w*.07f);c.drawRoundRect(new RectF(p,p,w-p,h-p),w*.26f,w*.26f,box);stroke.setStrokeWidth(Math.max(5,w*.095f));float x=w*.32f;c.drawLine(x,h*.24f,x,h*.76f,stroke);c.drawArc(new RectF(w*.26f,h*.20f,w*.72f,h*.53f),-92,190,false,stroke);c.drawArc(new RectF(w*.26f,h*.46f,w*.78f,h*.79f),-92,190,false,stroke);c.drawCircle(w*.74f,h*.25f,Math.max(2,w*.035f),dot);}}
